mapper.select:
select ws.*, cw.serial_number, cw.purchaser, bc.name as branch_company_name, u1.name as create_user_name, u2.name as audit_user_name from wms_waste_sale as ws left join wms_waste_sale_detail as wsd on ws.id = wsd.waste_sale_id left join contract_waste as cw on ws.contract_waste_id = cw.id left join sys_branch_company as bc on ws.branch_company_id = bc.id left join sys_user as u1 on ws.create_user_id = u1.id left join sys_user as u2 on ws.audit_user_id = u2.id where ws.bool_delete_enum = 0 and wsd.bool_delete_enum = 0
AND ws.audit_status_enum = #{auditStatusEnum}
AND DATE(ws.sale_date) >= DATE(#{startDate})
AND DATE(ws.sale_date) <= DATE(#{endDate})
AND ws.branch_company_id = #{branchCompanyId}
AND ws.plate_number like concat('%',#{plateNumber},'%')
AND ws.contract_waste_id = #{contractWasteId}
AND cw.serial_number like concat('%',#{serialNumber},'%')
AND cw.purchaser like concat('%',#{purchaser},'%')
AND wsd.waste_classification_id = #{wasteClassificationId}
AND u1.name like concat('%',#{createUserName},'%')
AND u2.name like concat('%',#{auditUserName},'%')
GROUP BY ws.id ORDER BY ws.audit_status_enum, ws.sale_date DESC, ws.id DESC

SELECT y_t.`year` as `dateTime`, IFNULL(temp1.mete, 0) as mete FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year`
) y_t LEFT JOIN ( select DATE_FORMAT(ws.sale_date, "%Y-%m") as `dateTime`, sum(wsd.sale_mete) as mete from wms_waste_sale as ws right join wms_waste_sale_detail as wsd on ws.id = wsd.waste_sale_id left join contract_waste as cw on ws.contract_waste_id = cw.id left join sys_branch_company as bc on ws.branch_company_id = bc.id where ws.bool_delete_enum = 0 and wsd.bool_delete_enum = 0
AND ws.branch_company_id = #{branchCompanyId}
AND DATE_FORMAT(ws.sale_date, "%Y") = DATE_FORMAT(#{yearDate}, "%Y")
group by DATE_FORMAT(ws.sale_date, "%Y-%m") ) AS temp1 ON temp1.dateTime = y_t.`year`

SELECT y_t.`year` as `dateTime`, IFNULL(temp1.mete, 0) as mete FROM (
select DATE_FORMAT(#{i}, '%Y') as `year`
) y_t LEFT JOIN ( select DATE_FORMAT(ws.sale_date, "%Y") as `dateTime`, sum(wsd.sale_mete) as mete from wms_waste_sale as ws right join wms_waste_sale_detail as wsd on ws.id = wsd.waste_sale_id left join contract_waste as cw on ws.contract_waste_id = cw.id left join sys_branch_company as bc on ws.branch_company_id = bc.id where ws.bool_delete_enum = 0 and wsd.bool_delete_enum = 0
AND ws.branch_company_id = #{branchCompanyId}
group by DATE_FORMAT(ws.sale_date, "%Y") ) AS temp1 ON temp1.dateTime = y_t.`year`
